import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { toJob, type JobRow } from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_FRESH_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectWorkerBeat = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'");
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, idempotency_key, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?, ?)`,
);

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
